contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account, uint256 amount, uint256 burnAmount) public {
        require(account != address(0), "account must not be zero");
        require(amount > 0, "mint amount must be positive");
        require(burnAmount > 0, "burn amount must be positive");
        require(burnAmount <= amount, "burn amount must not exceed minted amount");

        uint256 tokenId = c.uniqueTokensOutstanding();

        c.createGameItem("test item", "uri", false, true, 0, 0, 0);
        c.setAllowedBurningAddresses(address(this));
        c.mint(account, tokenId, amount);

        uint256 balanceBefore = c.balanceOf(account, tokenId);
        c.burn(account, tokenId, burnAmount);
        uint256 balanceAfter = c.balanceOf(account, tokenId);

        assert(balanceAfter == balanceBefore - burnAmount);
    }

    receive() external payable {}
}
